begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create temp table overhaul_fixture(w bigint,g bigint,early bigint,s bigint,edit jsonb);
do $$ declare s bigint; w bigint; g bigint; e bigint; begin
 insert into public.seasons(pool_id,year,status) select id,2098,'setup' from public.pools limit 1 returning id into s;
 insert into public.pool_weeks(season_id,week_number,label,lines_freeze_at) values(s,1,'Overhaul test',now()+interval '3 days') returning id into w;
 insert into public.games(week_id,away_team,home_team,kickoff_at,provider_event_id) values(w,'BUF','MIA',now()+interval '5 days','overhaul-game') returning id into g;
 insert into public.games(week_id,away_team,home_team,kickoff_at) values(w,'KC','DEN',now()+interval '2 hours') returning id into e;
 insert into public.pool_lines(game_id,away_spread,total,source,frozen_at) values(g,-3,44,'consensus',now()),(e,-4,45,'consensus',now());
 insert into overhaul_fixture select w,g,e,s,jsonb_build_object('game_id',g,'updated_at',l.updated_at,'away_spread',-7,'total',47,'spread_override',true,'total_override',false,'game_type','international') from public.pool_lines l where game_id=g;
end; $$;
grant select,update on overhaul_fixture to authenticated,service_role;
select ok(not has_function_privilege('authenticated','public.apply_odds_lines(bigint,jsonb,boolean)','execute'),'entrants cannot ingest odds');
select ok(not has_function_privilege('anon','public.save_line_batch(bigint,jsonb)','execute'),'anonymous cannot edit lines');
select ok(not has_function_privilege('authenticated','public.activate_espn_odds_automation()','execute'),'entrants cannot activate scheduler');
select throws_ok(format('insert into public.games(id,week_id,away_team,home_team,kickoff_at) values(%s,%s,''BUF'',''MIA'',now())',(select g from overhaul_fixture),(select w from overhaul_fixture)),'428C9',null,'reproduces generated-ID failure in the old upsert');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select ok(public.claim_odds_lease((select w from overhaul_fixture),'00000000-0000-0000-0000-000000000001'),'first worker takes lease');
select ok(not public.claim_odds_lease((select w from overhaul_fixture),'00000000-0000-0000-0000-000000000002'),'overlapping worker rejected');
select public.release_odds_lease((select w from overhaul_fixture),'00000000-0000-0000-0000-000000000001');
select is((public.apply_odds_lines((select w from overhaul_fixture),(select jsonb_build_array(jsonb_build_object('game_id',g,'away_spread',-5,'total',46,'spread_book','draftkings','total_book','betmgm','spread_observed_at',now(),'total_observed_at',now())) from overhaul_fixture))->>'applied')::integer,1,'provider writes an existing game line');
select is((public.apply_odds_lines((select w from overhaul_fixture),(select jsonb_build_array(jsonb_build_object('game_id',g,'away_spread',-5,'total',46,'spread_book','draftkings','total_book','betmgm','spread_observed_at',now(),'total_observed_at',now())) from overhaul_fixture))->>'unchanged')::integer,1,'successful no-change is recorded');
select is((public.apply_odds_lines((select w from overhaul_fixture),(select jsonb_build_array(jsonb_build_object('game_id',g,'away_spread',-9,'total',49,'spread_observed_at',now()-interval '1 day','total_observed_at',now()-interval '1 day')) from overhaul_fixture))->>'unchanged')::integer,1,'stale fields cannot replace saved observations');
reset role;
update overhaul_fixture f set edit=jsonb_set(edit,'{updated_at}',to_jsonb(l.updated_at)) from public.pool_lines l where l.game_id=f.g;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000010","role":"authenticated"}',true);
select lives_ok('select public.save_line_batch(w,jsonb_build_array(edit)) from overhaul_fixture','commissioner batch edit succeeds');
select is((select away_spread from public.pool_lines where game_id=(select g from overhaul_fixture)),-7::numeric,'manual value saved');
select ok((select spread_override and not total_override from public.pool_lines where game_id=(select g from overhaul_fixture)),'per-field override state saved');
select lives_ok('select public.save_side_pots(s,225,300) from overhaul_fixture','commissioner can configure pots independently');
select is((select ud_pot from public.seasons where id=(select s from overhaul_fixture)),300::numeric,'configured UD pot saved');
reset role;
update overhaul_fixture f set edit=jsonb_set(edit,'{updated_at}',to_jsonb(l.updated_at)) from public.pool_lines l where l.game_id=f.g;
set local role authenticated;
select throws_ok('select public.save_line_batch(w,jsonb_build_array(jsonb_set(edit,''{away_spread}'',''-8''::jsonb),jsonb_set(edit,''{updated_at}'',''"2000-01-01"''::jsonb))) from overhaul_fixture','P0001',null,'conflict aborts the entire batch');
select is((select away_spread from public.pool_lines where game_id=(select g from overhaul_fixture)),-7::numeric,'earlier row rolls back after conflict');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000099","role":"authenticated"}',true);
select throws_ok('select public.save_line_batch(w,jsonb_build_array(edit)) from overhaul_fixture','P0001','Commissioner access required','noncommissioner rejected');
select throws_ok('select public.save_side_pots(s,200,200) from overhaul_fixture','P0002',null,'noncommissioner cannot access season payout write');
reset role;
update public.games set kickoff_at=now()+interval '30 minutes' where id=(select early from overhaul_fixture);
update public.pool_weeks set lines_freeze_at=now()-interval '5 minutes' where id=(select w from overhaul_fixture);
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok('select public.apply_odds_lines(w,jsonb_build_array(jsonb_build_object(''game_id'',g,''away_spread'',-10,''total'',48,''spread_observed_at'',now(),''total_observed_at'',now()),jsonb_build_object(''game_id'',early,''away_spread'',-20,''total'',50)),true) from overhaul_fixture','final refresh succeeds with protected overrides and early deadline');
select is((select away_spread from public.pool_lines where game_id=(select g from overhaul_fixture)),-7::numeric,'manual spread survives final refresh');
select is((select total from public.pool_lines where game_id=(select g from overhaul_fixture)),48::numeric,'automatic total refreshed at final lock');
select is((select away_spread from public.pool_lines where game_id=(select early from overhaul_fixture)),-4::numeric,'earlier game lock retained');
select ok((select lines_frozen_at is not null from public.pool_weeks where id=(select w from overhaul_fixture)),'finalized board locked');
select is((public.apply_odds_lines((select w from overhaul_fixture),'[]',true)->>'applied')::integer,0,'repeat finalization is idempotent');
reset role;
update public.pool_weeks set lines_frozen_at=null where id=(select w from overhaul_fixture);
set local role service_role;
select lives_ok('select public.apply_odds_lines(w,''[]'',true) from overhaul_fixture','failed final fetch locks saved lines without replacements');
select ok((select lines_frozen_at is not null from public.pool_weeks where id=(select w from overhaul_fixture)),'empty final fetch still locks board');
select lives_ok('select public.save_final_game_result(g,20,10,''provider'',now(),false,''[]'',null) from overhaul_fixture','ESPN finalization commits');
select is((select status from public.games where id=(select g from overhaul_fixture)),'final','ESPN game finalized');
select is(public.save_final_game_result((select g from overhaul_fixture),20,10,'provider',now(),false,'[]',null),0,'repeated ESPN final is idempotent');
select throws_ok('select public.save_final_game_result(g,21,10,''provider'',now(),false,jsonb_build_array(jsonb_build_object(''entry_id'',999999999,''week_id'',w,''game_id'',g,''kind'',''ats'',''outcome'',''win'',''scoring_revision'',1,''decision_value'',1,''strike_delta'',0)),null) from overhaul_fixture','23503',null,'score event failure rolls back result transaction');
select is((select away_score from public.game_results where game_id=(select g from overhaul_fixture)),20::smallint,'failed score event write leaves prior result intact');
reset role;
update public.game_results set source='commissioner' where game_id=(select g from overhaul_fixture);
set local role service_role;
select is(public.save_final_game_result((select g from overhaul_fixture),99,0,'provider',now(),false,'[]',null),0,'provider cannot overwrite commissioner final');
select is((select away_score from public.games where id=(select g from overhaul_fixture)),20::smallint,'commissioner game scores remain intact');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000010","role":"authenticated"}',true);
select lives_ok('select public.release_score_override(g) from overhaul_fixture','commissioner can return final to ESPN control');
select is((select final_validation_state from public.games where id=(select g from overhaul_fixture)),'pending','returned result is queued for ESPN recovery');
reset role;
insert into public.odds_schedule_slots(expected_at,mode,attempts) values('2099-01-01','refresh',1);
set local role service_role;
select is((select count(*) from public.claim_odds_slot((select id from public.odds_schedule_slots where expected_at='2099-01-01'))),1::bigint,'scheduled attempt is claimed once');
select is((select count(*) from public.claim_odds_slot((select id from public.odds_schedule_slots where expected_at='2099-01-01'))),0::bigint,'duplicate delivery cannot call provider twice');
reset role;
select is(private.odds_job_mode('2026-10-11 16:00:00+00'),'initialize','Sunday noon EDT initialization');
select is(private.odds_job_mode('2026-11-08 17:00:00+00'),'initialize','Sunday noon EST initialization');
select is(private.odds_job_mode('2026-10-16 00:00:00+00'),'finalize','Thursday 8 PM EDT final lock');
select is(private.odds_job_mode('2026-11-06 01:00:00+00'),'finalize','Thursday 8 PM EST final lock');
select is(private.odds_job_mode('2026-11-02 07:00:00+00'),'refresh','Monday 2 AM refresh after DST change');
select is(private.odds_job_mode('2026-10-10 16:00:00+00'),null::text,'no Saturday refresh');
select ok(not has_table_privilege('anon','public.odds_schedule_slots','SELECT'),'anonymous users cannot discover scheduler table');
select ok(not has_table_privilege('authenticated','public.odds_schedule_slots','TRUNCATE'),'signed-in users cannot truncate scheduler history');
select ok(has_table_privilege('authenticated','public.odds_schedule_slots','SELECT'),'commissioner activity log remains readable under RLS');
select ok(has_table_privilege('service_role','public.odds_schedule_slots','UPDATE'),'scheduler service can record execution');
select * from finish();
rollback;
